/* Editable league definitions and browser-local presets. */
let setupPage='career',setupFilter='',setupQuery='',managerTab='teams',presetError='';
const PRESET_KEY='hoops-dynasty-presets-v1';
function makeDraft(){return{leagueName:'Dynasty Basketball League',year:2026,gmName:'',selectedKey:'team-ATL',meetings:82,cap:150,darkMode:preferredDarkMode(),leagueGender:'male',leagueSettings:{...LEAGUE_SETTING_DEFAULTS},teams:defaultTeams(),conferences:copy(DEFAULT_CONFERENCES),divisions:copy(DEFAULT_DIVISIONS)}}
function startCareer(){onLoadCareers=false;setupDraft=makeDraft();setupPage='career';setupFilter='';setupQuery='';onSetup=true;onTitle=false;render();window.scrollTo(0,0)}
function cancelSetup(){onSetup=false;onTitle=true;render();window.scrollTo(0,0)}
function captureSetup(){const f=document.getElementById('career-form');if(!f?.elements)return;const e=f.elements,d=setupDraft;for(const k of ['leagueName','gmName','leagueGender'])if(e[k])d[k]=e[k].value;for(const k of ['year','cap'])if(e[k])d[k]=Number(e[k].value);if(e.meetings)d.meetings=e.meetings.value==='custom'?'custom':Number(e.meetings.value);if(e.darkMode)d.darkMode=e.darkMode.checked;d.leagueSettings??={...LEAGUE_SETTING_DEFAULTS};let custom=false;for(const [key,,def,range] of LEAGUE_SETTING_FIELDS){const input=e['rule_'+key];if(!input)continue;const value=range==='date'?input.value.slice(-5):typeof def==='boolean'?input.value==='true':typeof def==='number'?Number(input.value):input.value;if(CUSTOM_SCHEDULE_KEYS.includes(key)&&value!==d.leagueSettings[key])custom=true;d.leagueSettings[key]=value}if(custom)d.meetings='custom'}
function selectedDraftTeam(){return setupDraft.teams.find(t=>t.key===setupDraft.selectedKey)||setupDraft.teams[0]}
function chooseSetupTeam(index){captureSetup();const t=setupDraft.teams[index];if(!t)return;setupDraft.selectedKey=t.key;renderSetup();document.querySelector(`[data-select-team="${index}"]`)?.focus({preventScroll:true})}
function randomTeam(){captureSetup();const t=setupDraft.teams[rand(0,setupDraft.teams.length-1)];setupDraft.selectedKey=t.key;setupQuery='';setupFilter='';renderSetup();toast(`Selected ${t.city} ${t.name}`)}
function refreshSetupSettings(){captureSetup();renderSetup()}
function preferredDarkMode(){try{const value=localStorage.getItem('hoops-dynasty-dark-mode');if(value!==null)return value==='true'}catch{}return typeof activeSaveId!=='undefined'&&!!activeSaveId?!!state.darkMode:false}
function applyLeagueTheme(){const dark=onSetup?!!setupDraft?.darkMode:!onTitle?!!state.darkMode:preferredDarkMode();if(onSetup||!onTitle){try{localStorage.setItem('hoops-dynasty-dark-mode',String(dark))}catch{}}document.documentElement.classList.toggle('league-dark',dark);document.documentElement.classList.toggle('league-light',!onSetup&&!onTitle&&!dark)}
function toggleCareerDark(value){state.darkMode=!!value;save();render()}
function syncAlignment(d){for(const t of d.teams){const div=d.divisions.find(v=>v.id===t.divisionId),conf=d.conferences.find(c=>c.id===(div?.conferenceId||(t.divisionId?'':t.conferenceId)));t.division=div?.name||'';t.conference=conf?.name||'';if(conf)t.conferenceId=conf.id;t.color=t.colors[0].hex}}
// Exactly what keeps a league from the 82-game format: team count, conference count, division sizes, conferences
// without three divisions, and teams with no division.
function alignmentProblems(d){
 const a=copy(d);syncAlignment(a);const size=v=>a.teams.filter(t=>t.divisionId===v.id).length,populated=a.conferences.filter(c=>a.teams.some(t=>t.conferenceId===c.id));
 const out={teams:a.teams.length!==30?a.teams.length:null,conferences:populated.length!==2?populated.length:null,divisions:a.divisions.filter(v=>size(v)>0&&size(v)!==5).map(v=>({id:v.id,name:v.name,teams:size(v)})),conferenceDivisions:populated.map(c=>({id:c.id,name:c.name,divisions:a.divisions.filter(v=>v.conferenceId===c.id&&size(v)>0).length})).filter(c=>c.divisions!==3),unassigned:a.teams.filter(t=>!t.divisionId).map(t=>t.abbr)};
 out.ok=out.teams===null&&out.conferences===null&&!out.divisions.length&&!out.conferenceDivisions.length&&!out.unassigned.length;return out;
}
function alignmentProblemText(p,advice=true){
 const parts=[];if(p.teams!==null)parts.push('This league has '+p.teams+' teams.');if(p.conferences!==null)parts.push('Teams are in '+p.conferences+' '+(p.conferences===1?'conference':'conferences')+'.');
 for(const c of p.conferenceDivisions)parts.push(c.name+' has '+c.divisions+' '+(c.divisions===1?'division':'divisions')+'.');
 if(p.divisions.length)parts.push(p.divisions.map((v,i)=>v.name+' has '+v.teams+(i===0?' '+(v.teams===1?'team':'teams'):'')).join(', ')+'.');
 if(p.unassigned.length)parts.push('No division: '+p.unassigned.join(', ')+'.');
 return '82-game seasons need 30 teams in two conferences, each with three five-team divisions. '+parts.join(' ')+(advice?' Adjust the alignment or choose a round-robin season.':'');
}
function setupFormatName(d){return d.meetings===82?'82-game format':d.meetings==='custom'?'custom schedule':'round-robin schedule ('+d.meetings+(d.meetings===1?' game':' games')+' per opponent)'}
// Schedule fit for a loaded preset; scope says which side came from the preset.
function setupFitIssue(d,scope='all'){
 let detail=null;const problems=d.meetings===82?alignmentProblems(d):null;if(problems&&!problems.ok)detail=alignmentProblemText(problems,false);
 if(!detail){try{validateSetupLeagueSettings(d)}catch(e){detail=e.message}}if(!detail)return null;const format=setupFormatName(d);
 return {scope,detail,problems,lead:scope==='structure'?'This preset’s teams don’t fit the current '+format+'.':scope==='settings'?'This preset’s '+format+' doesn’t fit your current teams.':'This preset’s teams don’t fit its '+format+'.'};
}
let setupAlignmentReview=null;
function validateDraft(d,requireGM=false,skipSchedule=false){if(!d||typeof d.leagueName!=='string'||!d.leagueName.trim()||d.leagueName.length>60||typeof d.gmName!=='string'||d.gmName.length>40||(requireGM&&!d.gmName.trim()))return 'Enter a league name and general manager name.';if(d.leagueGender!==undefined&&!LEAGUE_GENDERS.includes(d.leagueGender))return 'Choose a valid player gender setting.';if(typeof d.darkMode!=='boolean')return 'Choose a valid display mode.';if(!Number.isInteger(d.year)||d.year<1900||d.year>2100||![1,2,4,82,'custom'].includes(d.meetings)||!Number.isFinite(d.cap)||d.cap<.000001||d.cap>1000)return 'Choose valid season and salary settings.';if(!Array.isArray(d.teams)||d.teams.length<4||d.teams.length>36)return 'Keep between 4 and 36 teams in the league.';if(!Array.isArray(d.conferences)||!d.conferences.length||d.conferences.length>12||!Array.isArray(d.divisions)||d.divisions.length>30)return 'The league needs at least one conference.';for(const list of [d.conferences,d.divisions]){if(new Set(list.map(x=>x.id)).size!==list.length||list.some(x=>!/^[-a-z0-9]+$/i.test(x.id)||typeof x.name!=='string'||!x.name.trim()||x.name.length>35))return 'Conference or division names are invalid.'}if(d.divisions.some(v=>!d.conferences.some(c=>c.id===v.conferenceId)))return 'Every division needs a conference.';if(new Set(d.teams.map(t=>t.key)).size!==d.teams.length||new Set(d.teams.map(t=>t.abbr.toUpperCase())).size!==d.teams.length)return 'Team abbreviations must be unique.';for(const t of d.teams){if(!/^[-a-z0-9]+$/i.test(t.key)||typeof t.city!=='string'||!t.city.trim()||t.city.length>35||typeof t.name!=='string'||!t.name.trim()||t.name.length>35||!/^[A-Z0-9]{2,5}$/.test(t.abbr)||!validMetroPopulation(t.population)||t.marketSize!==marketSizeForPopulation(t.population)||!(d.divisions.some(v=>v.id===t.divisionId)||t.divisionId===''&&d.conferences.some(c=>c.id===t.conferenceId)))return 'Check team names, abbreviations, metro populations and divisions.';if(!Array.isArray(t.colors)||t.colors.length!==3||t.colors.some(c=>!/^#[0-9a-f]{6}$/i.test(c.hex)||typeof c.name!=='string'||c.name.length>35))return 'Each team needs three valid colors.';if(!['original','expansion','preset'].includes(t.logoAtlas)||!Number.isInteger(t.logoIndex)||t.logoIndex<0||t.logoIndex>=(t.logoAtlas==='original'?8:t.logoAtlas==='preset'?FRANCHISE_PRESETS.length:22))return 'Choose a valid team logo.'}if(d.meetings===82&&!skipSchedule){const aligned=copy(d);syncAlignment(aligned);if(!nbaAlignment(aligned.teams))return alignmentProblemText(alignmentProblems(d))}if(!skipSchedule){try{validateSetupLeagueSettings(d)}catch(e){return e.message}}return ''}
function submitCareer(event){event.preventDefault();captureSetup();const error=validateDraft(setupDraft,true);if(error)return toast(error);confirmNewCareer()}
async function confirmNewCareer(){if(!setupDraft||saveActionBusy)return;const error=validateDraft(setupDraft,true);if(error)return toast(error);saveActionBusy=true;careerFeedback('Creating and saving your career…');try{const nextState=buildSetupCareer(setupDraft),record=await createCareerRecord(nextState);activeSaveId=record.id;state=record.data||nextState;closeTitleModal();onSetup=false;onTitle=false;onLoadCareers=false;view='Overview';notice='Saved in this browser';render();window.scrollTo(0,0);showOwnerWelcome();save()}catch(error){careerFeedback(error.message,true)}finally{saveActionBusy=false}}
/* Team color names are no longer typed. A picked color gets a descriptive name from its hue; an unchanged
   color keeps its name; a name supplied by a preset (hidden field differs from the current name) is kept. */
function colorNameForHex(hex){const n=parseInt(String(hex).slice(1),16),r=(n>>16&255)/255,g=(n>>8&255)/255,b=(n&255)/255,max=Math.max(r,g,b),min=Math.min(r,g,b),l=(max+min)/2,d=max-min,s=d?d/(1-Math.abs(2*l-1)):0;
 if(s<.14||d<.12)return l<.12?'Black':l<.3?'Charcoal':l<.55?'Slate gray':l<.82?'Silver':'White';
 const h=(max===r?((g-b)/d+6)%6:max===g?(b-r)/d+2:(r-g)/d+4)*60,hue=[[15,'red'],[36,'orange'],[65,'gold'],[90,'lime'],[150,'green'],[185,'teal'],[205,'sky blue'],[245,'blue'],[275,'indigo'],[300,'purple'],[330,'magenta'],[350,'pink'],[361,'red']].find(([cut])=>h<cut)[1];
 const name=(l<.28?'Deep ':l>.72?'Light ':'')+hue;return name[0].toUpperCase()+name.slice(1)}
function teamColorName(previous,hex,submitted){const given=String(submitted??'').trim().slice(0,35);if(given&&given!==previous?.name)return given;if(previous&&String(previous.hex).toUpperCase()===String(hex).toUpperCase())return previous.name;return colorNameForHex(hex)}
function teamLogo(t,large=false){if(t.primaryLogo&&validTeamLogo(t.primaryLogo))return `<img class="franchise-logo custom-team-logo ${large?'logo-large':''}" src="${t.primaryLogo}" alt="${escapeHTML(t.city+' '+t.name)} logo">`;const expanded=t.logoAtlas==='expansion',preset=t.logoAtlas==='preset',cols=expanded?6:4,rows=expanded?4:preset?Math.ceil(FRANCHISE_PRESETS.length/4):2;return `<span class="franchise-logo ${expanded?'logo-expansion':''}${preset?'logo-preset':''} ${large?'logo-large':''}" role="img" aria-label="${escapeHTML(t.city+' '+t.name)} logo" style="--logo-x:${(t.logoIndex%cols)*100/(cols-1)}%;--logo-y:${Math.floor(t.logoIndex/cols)*100/(rows-1)}%"></span>`}
function teamChoice(t,i){return `<article class="team-card-shell"><button type="button" data-select-team="${i}" class="team-choice franchise-choice ${setupDraft.selectedKey===t.key?'selected':''}" aria-pressed="${setupDraft.selectedKey===t.key}" onclick="chooseSetupTeam(${i})"><span class="franchise-card-heading">${teamLogo(t)}<span class="franchise-card-name"><small>${escapeHTML(t.city)}</small><strong>${escapeHTML(t.name)}</strong></span><span class="team-check" aria-hidden="true">${setupDraft.selectedKey===t.key?'✓':''}</span></span><span class="franchise-card-facts"><span><small>Metro</small><b>${metroPopulationLabel(t.population)} · ${t.marketSize}</b></span><span><small>Conference</small><b>${escapeHTML(t.conference)}</b></span><span><small>Division</small><b>${escapeHTML(t.division)}</b></span></span><span class="franchise-card-colors">${t.colors.map((c,j)=>`<span title="${['Primary','Secondary','Tertiary'][j]}: ${escapeHTML(c.name)} (${c.hex})"><i style="background:${c.hex}"></i><small>${['Primary','Secondary','Tertiary'][j]}</small></span>`).join('')}</span></button><button type="button" class="edit-card" onclick="openTeamEditor(${i},'setup')">Edit team</button></article>`}
function selectedTeamProfile(t){return `<section class="setup-selected franchise-profile"><div class="eyebrow">YOUR FRANCHISE</div>${teamLogo(t,true)}<p>${escapeHTML(t.city.toUpperCase())}</p><h2>${escapeHTML(t.name.toUpperCase())}</h2><dl class="franchise-details"><div><dt>Metro population</dt><dd>${metroPopulationLabel(t.population)} · ${t.marketSize} market</dd></div><div><dt>Conference</dt><dd>${escapeHTML(t.conference)}</dd></div><div><dt>Division</dt><dd>${escapeHTML(t.division)}</dd></div></dl><div class="franchise-palette"><h3>TEAM COLORS</h3>${t.colors.map((c,j)=>`<div class="palette-color"><i style="background:${c.hex}" aria-hidden="true"></i><div><small>${['Primary','Secondary','Tertiary'][j]}</small><strong>${escapeHTML(c.name)}</strong></div><code>${c.hex}</code></div>`).join('')}</div></section>`}
function filteredTeams(){return setupDraft.teams.map((t,i)=>({t,i})).filter(({t})=>(!setupFilter||(setupDraft.divisions.find(d=>d.id===t.divisionId)?.conferenceId||t.conferenceId)===setupFilter)&&(!setupQuery||(t.city+' '+t.name+' '+t.abbr).toLowerCase().includes(setupQuery.toLowerCase())))}
function updateTeamFilter(){setupFilter=document.getElementById('team-conference').value;setupQuery=document.getElementById('team-search').value;document.getElementById('team-grid').innerHTML=filteredTeams().map(({t,i})=>teamChoice(t,i)).join('')||'<p class="empty">No matching teams.</p>';document.getElementById('team-count').textContent=filteredTeams().length+' of '+setupDraft.teams.length+' teams'}
// The season year is the year the season ends; show what it means for this calendar.
function setupSeasonMeaning(d){const r=d.leagueSettings||{},cross=d.meetings!=='custom'||(r.seasonEnd||'04-19')<(r.seasonStart||'10-28'),y=Number(d.year);if(!Number.isInteger(y))return '';return y+' → '+(cross?(y-1)+'–'+String(y).slice(-2):y)+' season'}
function renderSetup(){if(setupPage==='settings')return renderSetupLeagueSettings();const d=setupDraft;syncAlignment(d);applyLeagueTheme();const t=selectedDraftTeam();document.getElementById('app').innerHTML=`<main class="setup-page"><header class="setup-top"><button type="button" onclick="cancelSetup()">← Back to title</button><span>HOOPS DYNASTY</span><small>THE BLUEPRINT</small></header><div class="setup-wrap"><div class="setup-heading"><div><div class="eyebrow">YOUR NEXT CHAPTER</div><h1>NEW CAREER</h1><p>${d.teams.length} teams. Your league. Your legacy.</p></div><div class="actions"><button class="setup-tool" type="button" onclick="openPresets()">Presets</button><button class="setup-tool" type="button" onclick="openLeagueManager()">Manage league</button></div></div>${setupPageNavigation()}<form id="career-form" onsubmit="submitCareer(event)"><div class="setup-grid"><div><section class="setup-section"><h2><span>01</span> Career details</h2><div class="setup-fields"><label class="wide">League name<input name="leagueName" value="${escapeHTML(d.leagueName)}" required maxlength="60" oninput="captureSetup()"></label><label>Starting season<input name="year" type="number" min="1900" max="2100" step="1" value="${d.year}" required onchange="captureSetup()" oninput="this.parentElement.querySelector('.setup-season-meaning').textContent=setupSeasonMeaning({...setupDraft,year:Number(this.value)})"><small class="setup-season-meaning">${setupSeasonMeaning(d)}</small></label><label>General manager name<input name="gmName" value="${escapeHTML(d.gmName)}" required maxlength="40" placeholder="Your name" autocomplete="name" oninput="captureSetup()"></label></div></section><section class="setup-section"><div class="section-action-heading"><h2><span>02</span> Select your team</h2><div class="actions"><button type="button" class="setup-tool" onclick="openAddSetupTeam()">+ Add Team</button><button type="button" class="setup-tool" onclick="randomTeam()">⚄ Random team</button></div></div><div class="team-filter"><label>Find a team<input id="team-search" type="search" value="${escapeHTML(setupQuery)}" placeholder="City or team name" oninput="updateTeamFilter()"></label><label>Conference<select id="team-conference" onchange="updateTeamFilter()"><option value="">All conferences</option>${d.conferences.map(c=>`<option value="${c.id}" ${setupFilter===c.id?'selected':''}>${escapeHTML(c.name)}</option>`).join('')}</select></label></div><p id="team-count" class="setup-help team-count">${filteredTeams().length} of ${d.teams.length} teams</p><div id="team-grid" class="team-picker" role="group" aria-label="Select your team">${filteredTeams().map(({t,i})=>teamChoice(t,i)).join('')||'<p class="empty">No matching teams.</p>'}</div><p class="team-profile-footnote">Market tiers are fictional profiles. All teams share a league-wide schedule and playoff race.</p></section></div><div class="setup-side">${selectedTeamProfile(t)}<div class="side-start"><button type="submit" class="setup-start">START CAREER</button><button type="button" class="setup-tool" onclick="openPresets()">Save a preset</button></div></div></div><div class="setup-bottom"><p>Career saves and presets stay in this browser.</p><div class="actions"><button type="button" onclick="cancelSetup()">Cancel</button><button type="submit" class="setup-start">START CAREER</button></div></div></form></div></main>`}
function editorModal(title,html){titleModal(escapeHTML(title),html);document.getElementById('profile').classList.add('league-editor');applyLeagueTheme()}
function openLeagueManager(tab='teams',capture=true){if(capture)captureSetup();managerTab=tab;syncAlignment(setupDraft);editorModal('Manage league',`<p>Edit this new-career league, then save a preset to reuse it. Your active career is unchanged.</p><div class="editor-tabs" role="group" aria-label="League editor views"><button class="${tab==='teams'?'current':''}" onclick="openLeagueManager('teams',false)">Teams (${setupDraft.teams.length})</button><button class="${tab==='alignment'?'current':''}" onclick="openLeagueManager('alignment',false)">Conferences & divisions</button></div>${tab==='teams'?managerTeams():managerAlignment()}<div class="editor-footer"><button onclick="closeTitleModal();renderSetup()" class="primary">Done</button></div>`)}
function divisionOptions(selected,d=setupDraft){return d.conferences.map(c=>`<optgroup label="${escapeHTML(c.name)}"><option value="@${c.id}" ${selected==='@'+c.id?'selected':''}>No division</option>${d.divisions.filter(v=>v.conferenceId===c.id).map(v=>`<option value="${v.id}" ${selected===v.id?'selected':''}>${escapeHTML(v.name)}</option>`).join('')}</optgroup>`).join('')}
function managerTeams(){return `<div class="manager-team-list">${setupDraft.teams.map((t,i)=>`<div class="manager-team-row">${teamLogo(t)}<div class="manager-name"><strong>${escapeHTML(t.city+' '+t.name)}</strong><small>${escapeHTML(t.conference)} · ${escapeHTML(t.division)}</small></div><label><span class="sr-label">Move ${escapeHTML(t.city+' '+t.name)} to division</span><select aria-label="Move ${escapeHTML(t.name)} to division" onchange="moveDraftTeam(${i},this.value)">${divisionOptions(t.divisionId||'@'+t.conferenceId)}</select></label><button onclick="openTeamEditor(${i},'manager')">Edit</button><button class="danger-button" onclick="askDeleteTeam(${i})" ${setupDraft.teams.length<=4?'disabled':''}>Delete</button></div>`).join('')}</div><p class="muted">At least four teams are required. Moving a team to a division also sets its conference.</p>`}
function moveDraftTeam(index,divisionId){const t=setupDraft.teams[index];if(!t)return;if(divisionId.startsWith('@')){const conf=setupDraft.conferences.find(c=>c.id===divisionId.slice(1));if(!conf)return;t.divisionId='';t.conferenceId=conf.id}else{if(!setupDraft.divisions.some(v=>v.id===divisionId))return;t.divisionId=divisionId;}syncAlignment(setupDraft);renderSetup();openLeagueManager('teams',false)}
function openTeamEditor(index,origin='setup'){captureSetup();const t=setupDraft.teams[index];if(!t)return;editorModal('Edit '+t.city+' '+t.name,`<form id="team-edit-form" onsubmit="saveTeamEdit(event,${index},'${origin}')">${moveCityField(t.city,setupDraft.teams.filter(x=>x!==t).map(x=>x.city))}<div class="editor-fields"><label>City<input name="city" onchange="this.form.elements.elevationFt.value=''" maxlength="35" required value="${escapeHTML(t.city)}"></label><label>Team name<input name="teamName" maxlength="35" required value="${escapeHTML(t.name)}"></label><label>Abbreviation<input name="abbr" pattern="[A-Za-z0-9]{2,5}" maxlength="5" required value="${escapeHTML(t.abbr)}"></label><label>Arena name<input name="arenaName" maxlength="80" required value="${escapeHTML(teamArena(t))}"></label><label>Stadium capacity<input name="stadiumCapacity" type="number" min="1" max="100000" step="1" required value="${t.stadiumCapacity??18000}"><small>Total seats for this team’s new-career arena.</small></label>${altitudeEditorFields(t)}${metroPopulationField('population',t.population)}<label>Division / conference<select name="division">${divisionOptions(t.divisionId||'@'+t.conferenceId)}</select></label><label>Default primary logo<select name="logo">${logoChoices().map((logo,i)=>`<option value="${i}" ${t.logoAtlas===logo.logoAtlas&&t.logoIndex===logo.logoIndex?'selected':''}>${escapeHTML(logo.city+' '+logo.name)}</option>`).join('')}</select></label></div>${managementLogoFields(t)}<h3 class="editor-subtitle">Team colors</h3><div class="editor-color-grid">${t.colors.map((c,j)=>`<label>${['Primary','Secondary','Tertiary'][j]}<input type="color" name="color${j}" value="${c.hex}" aria-label="${['Primary','Secondary','Tertiary'][j]} color"><input type="hidden" name="colorName${j}" value="${escapeHTML(c.name)}"></label>`).join('')}</div><p class="muted">Color swatches and team accents update. Logo artwork keeps its original palette.</p><div class="actions"><button type="button" onclick="${origin==='manager'?"openLeagueManager('teams',false)":'closeTitleModal()'}">Cancel</button><button type="submit" class="primary">Save team</button></div></form>`)}
function applyTeamEdit(index,values){const t=setupDraft.teams[index];if(!t)throw Error('Team not found.');const candidate={...altitudeEditedTeam(copy(t),values),city:values.city.trim(),name:values.name.trim(),abbr:values.abbr.trim().toUpperCase(),...metroPopulationEdit(values.population,t.population,values.city),...(values.arenaName!==undefined?{arenaName:values.city.trim()!==t.city&&values.arenaName.trim()===t.city+' Arena'?values.city.trim()+' Arena':values.arenaName.trim()}:t.arenaName&&t.arenaName===t.city+' Arena'&&values.city.trim()!==t.city?{arenaName:values.city.trim()+' Arena'}:{}),divisionId:values.divisionId.startsWith('@')?'':values.divisionId,conferenceId:values.divisionId.startsWith('@')?values.divisionId.slice(1):t.conferenceId,colors:copy(values.colors)};const logo=logoChoices()[values.logo];if(!logo)throw Error('Select a valid logo.');candidate.logoAtlas=logo.logoAtlas;candidate.logoIndex=logo.logoIndex;for(const kind of ['primary','secondary']){const key=kind+'Logo';if(values[kind+'Reset'])delete candidate[key];if(values[key]!==undefined&&values[key]!==null)candidate[key]=values[key]}if(values.secondaryLogoIndex!==undefined)candidate.secondaryLogoIndex=Number(values.secondaryLogoIndex);if(values.stadiumCapacity!==undefined)candidate.stadiumCapacity=Number(values.stadiumCapacity);readTeamBrand(candidate,message=>{throw Error(message)});candidate.colors.forEach((c,i)=>{c.role=['Primary','Secondary','Tertiary'][i];c.name=c.name.trim()||c.role;c.hex=c.hex.toUpperCase()});const draft=copy(setupDraft);draft.teams[index]=candidate;const error=validateDraft(draft,false,true);if(error)throw Error(error);setupDraft.teams[index]=candidate;syncAlignment(setupDraft)}
async function saveTeamEdit(event,index,origin){event.preventDefault();const form=event.currentTarget||document.getElementById('team-edit-form');if(form.dataset.saving)return;const e=form.elements,draft=setupDraft,original=draft.teams[index],values={elevationFt:e.elevationFt.value,...(e.lat?{lat:e.lat.value,lon:e.lon.value}:{}),city:e.city.value,name:e.teamName.value,abbr:e.abbr.value,...(e.arenaName?{arenaName:e.arenaName.value}:{}),population:e.population.value,stadiumCapacity:Number(e.stadiumCapacity.value),divisionId:e.division.value,logo:Number(e.logo.value),secondaryLogoIndex:Number(e.secondaryLogoIndex.value),primaryReset:e.primaryReset.checked,secondaryReset:e.secondaryReset.checked,colors:[0,1,2].map(i=>({name:teamColorName(original.colors[i],e['color'+i].value,e['colorName'+i].value),hex:e['color'+i].value}))};form.dataset.saving='true';form.querySelectorAll('button').forEach(b=>b.disabled=true);try{values.primaryLogo=await readLogoUpload(e.primaryUpload.files?.[0]);values.secondaryLogo=await readLogoUpload(e.secondaryUpload.files?.[0]);if(document.getElementById('team-edit-form')!==form||setupDraft!==draft||draft.teams[index]!==original)return;applyTeamEdit(index,values);renderSetup();if(origin==='manager')openLeagueManager('teams',false);else closeTitleModal();toast('Team updated')}catch(error){toast(error.message)}finally{delete form.dataset.saving;form.querySelectorAll('button').forEach(b=>b.disabled=false)}}
function askDeleteTeam(index){const t=setupDraft.teams[index];if(!t||setupDraft.teams.length<=4)return;editorModal('Delete team?',`<p>Remove ${escapeHTML(t.city+' '+t.name)} from this setup? Its games will be removed when the new schedule is created.</p><div class="actions"><button onclick="openLeagueManager('teams',false)">Cancel</button><button class="danger-button" onclick="deleteDraftTeam(${index})">Delete team</button></div>`)}
function deleteDraftTeam(index){if(setupDraft.teams.length<=4)return toast('Keep at least four teams.');const removed=setupDraft.teams.splice(index,1)[0];if(!removed)return;if(setupDraft.selectedKey===removed.key)setupDraft.selectedKey=setupDraft.teams[0].key;renderSetup();openLeagueManager('teams',false)}
function managerAlignment(){const d=setupDraft,problems=d.meetings===82?alignmentProblems(d):null,badDivision=id=>problems?.divisions.find(v=>v.id===id),badConference=id=>problems?.conferenceDivisions.find(c=>c.id===id),flag='style="border-left:4px solid #c2410c;padding-left:8px"';return `${setupAlignmentBanner()}${problems?.unassigned.length?`<p class="alignment-problem" ${flag}><strong>No division:</strong> ${problems.unassigned.map(escapeHTML).join(' · ')} <button type="button" onclick="openLeagueManager('teams',false)">Assign teams</button></p>`:''}<div class="alignment-add"><form onsubmit="addAlignment(event,'conference')"><label>New conference<input name="label" required maxlength="35" placeholder="Conference name"></label><button>Add conference</button></form><form onsubmit="addAlignment(event,'division')"><label>New division<input name="label" required maxlength="35" placeholder="Division name"></label><label>Conference<select name="conferenceId">${d.conferences.map(c=>`<option value="${c.id}">${escapeHTML(c.name)}</option>`).join('')}</select></label><button>Add division</button></form></div>${d.conferences.map((c,ci)=>`<section class="conference-block"><div class="conference-heading"><h3>${escapeHTML(c.name)} <small>${d.teams.filter(t=>(d.divisions.find(v=>v.id===t.divisionId)?.conferenceId||t.conferenceId)===c.id).length} teams</small>${badConference(c.id)?` <small class="alignment-problem-text">· ${badConference(c.id).divisions} divisions with teams — 82 games need 3</small>`:''}</h3><button onclick="editAlignment('conference',${ci})">Edit</button><button class="danger-button" onclick="askDeleteAlignment('conference',${ci})" ${d.conferences.length<=1?'disabled':''}>Delete</button></div>${d.divisions.map((v,vi)=>v.conferenceId===c.id?`<div class="division-row${badDivision(v.id)?' alignment-problem':''}" ${badDivision(v.id)?flag:''}><div><strong>${escapeHTML(v.name)}</strong>${badDivision(v.id)?` <small class="alignment-problem-text">${badDivision(v.id).teams} teams — needs 5</small>`:''}<p>${d.teams.filter(t=>t.divisionId===v.id).map(t=>escapeHTML(t.abbr)).join(' · ')||'No teams'}</p></div><button onclick="editAlignment('division',${vi})">Edit / move</button><button class="danger-button" onclick="askDeleteAlignment('division',${vi})" >Delete</button></div>`:'').join('')||'<p>No divisions yet.</p>'}</section>`).join('')}<p class="muted">Move teams out before deleting a division. Remove or move divisions before deleting a conference.</p>`}
function newStructureId(prefix){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8)}
function addAlignment(event,type){event.preventDefault();const f=event.target,label=f.elements.label.value.trim();if(!label)return;const list=type==='conference'?setupDraft.conferences:setupDraft.divisions;if(list.some(x=>x.name.toLowerCase()===label.toLowerCase()))return toast('That name is already in use.');if(list.length>=(type==='conference'?12:30))return toast('Maximum reached.');const record={id:newStructureId(type),name:label};if(type==='division')record.conferenceId=f.elements.conferenceId.value;list.push(record);renderSetup();openLeagueManager('alignment',false)}
function editAlignment(type,index){const record=(type==='conference'?setupDraft.conferences:setupDraft.divisions)[index];editorModal('Edit '+type,`<form onsubmit="saveAlignment(event,'${type}',${index})"><label>Name<input name="label" required maxlength="35" value="${escapeHTML(record.name)}"></label>${type==='division'?`<label>Conference<select name="conferenceId">${setupDraft.conferences.map(c=>`<option value="${c.id}" ${record.conferenceId===c.id?'selected':''}>${escapeHTML(c.name)}</option>`).join('')}</select></label><p class="muted">Moving this division moves all of its teams to the selected conference.</p>`:''}<div class="actions"><button type="button" onclick="openLeagueManager('alignment',false)">Cancel</button><button class="primary">Save ${type}</button></div></form>`)}
function saveAlignment(event,type,index){event.preventDefault();const e=event.target.elements,label=e.label.value.trim(),list=type==='conference'?setupDraft.conferences:setupDraft.divisions;if(!label||label.length>35)return;if(list.some((x,i)=>i!==index&&x.name.toLowerCase()===label.toLowerCase()))return toast('That name is already in use.');list[index].name=label;if(type==='division')list[index].conferenceId=e.conferenceId.value;syncAlignment(setupDraft);renderSetup();openLeagueManager('alignment',false)}
function askDeleteAlignment(type,index){const list=type==='conference'?setupDraft.conferences:setupDraft.divisions,record=list[index];if(type==='conference'&&list.length<=1)return toast('Keep at least one conference.');if(type==='conference'&&(setupDraft.divisions.some(v=>v.conferenceId===record.id)||setupDraft.teams.some(t=>!t.divisionId&&t.conferenceId===record.id)))return toast('Move or delete its divisions first.');if(type==='division'&&setupDraft.teams.some(t=>t.divisionId===record.id))return toast('Move its teams to another division first.');editorModal('Delete '+type+'?',`<p>Delete ${escapeHTML(record.name)}? This ${type} is empty.</p><div class="actions"><button onclick="openLeagueManager('alignment',false)">Cancel</button><button class="danger-button" onclick="deleteAlignment('${type}',${index})">Delete</button></div>`)}
function deleteAlignment(type,index){const list=type==='conference'?setupDraft.conferences:setupDraft.divisions,record=list[index];if(!record||type==='conference'&&list.length<=1)return;if(type==='conference'&&(setupDraft.divisions.some(v=>v.conferenceId===record.id)||setupDraft.teams.some(t=>!t.divisionId&&t.conferenceId===record.id))||type==='division'&&setupDraft.teams.some(t=>t.divisionId===record.id))return;list.splice(index,1);setupFilter='';renderSetup();openLeagueManager('alignment',false)}
// readPresets / writePresets: preset-storage.js
function presetPayload(scope){const d=setupDraft,out={};if(scope!=='structure')Object.assign(out,{leagueName:d.leagueName,year:d.year,gmName:d.gmName,meetings:d.meetings,cap:d.cap,darkMode:d.darkMode,leagueGender:d.leagueGender||'male',leagueSettings:copy(setupLeagueRules(d))});if(scope!=='settings')Object.assign(out,{teams:copy(d.teams),conferences:copy(d.conferences),divisions:copy(d.divisions),selectedKey:d.selectedKey});return out}
function scopeLabel(scope){return{all:'League + settings',structure:'Teams + alignment',settings:'Settings only'}[scope]||'Unknown'}
function openPresets(capture=true){if(capture)captureSetup();const list=readPresets();editorModal('League presets',`<p>Save settings, edited teams, and league alignment for future careers. Loading a preset changes only this setup.</p><form class="preset-create" onsubmit="savePreset(event)"><label>Preset name<input name="label" required maxlength="60" placeholder="e.g. My 30-team league"></label><label>Include<select name="scope"><option value="all">League + settings</option><option value="structure">Teams + alignment only</option><option value="settings">Settings only</option></select></label><button class="primary">Save new preset</button></form>${presetBackupMarkup()}${presetError?`<p role="alert">${escapeHTML(presetError)}</p>`:''}<div class="preset-list">${list.map((p,i)=>`<article class="preset-row"><div><h3>${escapeHTML(p.name)}</h3><p>${scopeLabel(p.scope)}${p.data?.teams?' · '+p.data.teams.length+' teams':''}</p><small>${escapeHTML(new Date(p.updatedAt).toLocaleDateString())}</small></div><div class="actions"><button onclick="askLoadPreset(${i})">Load</button><button onclick="askUpdatePreset(${i})">Update</button><button class="danger-button" onclick="askDeletePreset(${i})">Delete</button></div></article>`).join('')||'<p class="empty">No presets yet. Save your first league above.</p>'}</div>`)}
async function createPreset(name,scope){name=name.trim();if(!name||name.length>60||!['all','structure','settings'].includes(scope))throw Error('Enter a preset name and scope.');const error=validateDraft(setupDraft);if(error)throw Error(error);const list=readPresets();if(presetError)throw Error(presetError);if(list.length>=30)throw Error('Keep at most 30 presets. Delete an old preset first.');if(list.some(p=>p.name.toLowerCase()===name.toLowerCase()))throw Error('That name exists. Use Update on the saved preset.');list.push({id:newStructureId('preset'),name,scope,updatedAt:new Date().toISOString(),data:presetPayload(scope)});if(!await writePresets(list))throw Error('Preset not saved.');return list.length-1}
async function savePreset(event){event.preventDefault();try{await createPreset(event.target.elements.label.value,event.target.elements.scope.value);openPresets(false);toast('Preset saved in this browser.')}catch(error){toast(error.message)}}
function askLoadPreset(index){const p=readPresets()[index];if(!p)return;editorModal('Load preset?',`<p>Apply ${escapeHTML(p.name)} (${scopeLabel(p.scope)})? Matching fields in this setup will be replaced.</p><div class="actions"><button onclick="openPresets(false)">Cancel</button><button class="primary" onclick="loadPreset(${index})">Apply preset</button></div>`)}
function applyPreset(index){const p=readPresets()[index];if(!p||!['all','structure','settings'].includes(p.scope)||!p.data)throw Error('Preset could not be loaded.');const candidate=copy(setupDraft);for(const key of ['leagueName','year','gmName','meetings','cap','darkMode','leagueGender','leagueSettings','teams','conferences','divisions','selectedKey'])if(Object.hasOwn(p.data,key))candidate[key]=copy(p.data[key]);if(p.scope!=='structure'&&!p.data.leagueSettings){candidate.leagueSettings={...LEAGUE_SETTING_DEFAULTS};syncSetupScheduleDefaults(candidate)}if(Array.isArray(candidate.teams))candidate.teams.forEach(t=>t&&typeof t==='object'&&withMetroPopulation(t,{keepTier:true}));
 // Corrupt data (names, colors, logos, settings values) still blocks the load; alignment and schedule fit do not.
 const error=validateDraft(candidate,false,true);if(error)throw Error('Preset is invalid: '+error);try{setupLeagueRules(candidate)}catch(e){throw Error('Preset is invalid: '+e.message)}
 if(!candidate.teams.some(t=>t.key===candidate.selectedKey))candidate.selectedKey=candidate.teams[0].key;syncAlignment(candidate);setupDraft=candidate;setupFilter='';setupQuery='';setupAlignmentReview=setupFitIssue(candidate,p.scope);return setupAlignmentReview}
function loadPreset(index){try{const fit=applyPreset(index);renderSetup();if(fit){openLeagueManager('alignment',false);toast('Preset applied. '+fit.lead)}else{closeTitleModal();toast('Preset applied.')}}catch(error){toast(error.message)}}
function setupFixDivisions(){document.querySelector('.alignment-problem button')?.focus()}
function setupSwitchSchedule(meetings){if(![1,2,'custom'].includes(meetings))return;setupDraft.meetings=meetings;if(meetings==='custom')syncSetupScheduleDefaults(setupDraft);const fit=setupFitIssue(setupDraft,setupAlignmentReview?.scope||'all');setupAlignmentReview=fit;renderSetup();openLeagueManager('alignment',false);toast(fit?'Schedule changed, but it still needs attention: '+fit.detail:'Schedule switched to '+setupFormatName(setupDraft)+'.')}
function setupAlignmentBanner(){
 const d=setupDraft,fit=setupFitIssue(d,setupAlignmentReview?.scope||'all');if(!fit)return '';const lead=setupAlignmentReview?fit.lead:d.meetings===82?'This alignment doesn’t fit the 82-game format.':'This league doesn’t fit the '+setupFormatName(d)+'.';
 return `<div class="note alignment-banner" role="alert" style="border-left:4px solid #c2410c"><strong style="color:#9a3412;display:block">${escapeHTML(lead)}</strong><p>${escapeHTML(fit.detail)}</p><div class="actions">${fit.problems&&!fit.problems.ok?'<button type="button" onclick="setupFixDivisions()">Fix the divisions</button>':''}${d.meetings!==2?'<button type="button" onclick="setupSwitchSchedule(2)">Switch to round-robin</button>':''}${d.meetings!=='custom'?'<button type="button" onclick="setupSwitchSchedule(\'custom\')">Use a custom schedule</button>':''}</div></div>`;
}
function askUpdatePreset(index){const p=readPresets()[index];if(!p)return;editorModal('Update preset?',`<p>Replace ${escapeHTML(p.name)} with your current ${scopeLabel(p.scope).toLowerCase()}?</p><div class="actions"><button onclick="openPresets(false)">Cancel</button><button class="primary" onclick="updatePreset(${index})">Update preset</button></div>`)}
async function updatePreset(index){const list=readPresets(),p=list[index],error=validateDraft(setupDraft);if(error)return toast(error);if(!p)return;p.data=presetPayload(p.scope);p.updatedAt=new Date().toISOString();if(await writePresets(list)){openPresets(false);toast('Preset updated.')}}
function askDeletePreset(index){const p=readPresets()[index];if(!p)return;editorModal('Delete preset?',`<p>Delete ${escapeHTML(p.name)}? Your current setup and career will remain.</p><div class="actions"><button onclick="openPresets(false)">Cancel</button><button class="danger-button" onclick="deletePreset(${index})">Delete preset</button></div>`)}
async function deletePreset(index){const list=readPresets();list.splice(index,1);if(await writePresets(list))openPresets(false)}
applyLeagueTheme();
